# -*- coding: utf-8 -*-
P1 = "Cari kalimat yang menyatakan pendapat/alasan penulis (〜からだ、〜と思う、しかし〜)."
P2 = "Cocokkan setiap pilihan dengan teks; pilihan yang menambahkan hal yang tidak ada di teks adalah salah."
JN = 'Teks panjang (内容理解・長文)'
W = ['Tidak disebut dalam teks.', 'Tidak sesuai dengan isi teks.', 'Bertentangan dengan isi teks.']
def Cc(jp, idt, qs): return dict(slot='cho', jenis=JN, jp=jp, id=idt, qs=qs)
def Q(q, opts, ans, alasan, bukti, wrong=W, poin=P1): return (q, opts, ans, alasan, bukti, wrong, poin)
B = [
 Cc('最近、都会から地方へ移り住む人が増えている。きっかけの一つは、リモートワークが広まり、会社に通わなくても働けるようになったことだ。家賃が安く、自然の多い環境で子どもを育てたいと考える家庭も多い。\nしかし、実際に移り住んでみると、予想外の問題に直面することがある。例えば、車がないと買い物や通院ができない、近所づきあいが思っていたより密で戸惑う、などだ。地方では、地域の行事に参加することが当たり前とされている場合もある。\nそのため、移住を決める前に、何度かその町を訪れ、実際の暮らしを体験しておくことが大切だと言われている。自治体の中には、短期間の「お試し移住」の制度を用意しているところもある。',
    'Belakangan makin banyak orang pindah dari kota besar ke daerah. Salah satu pemicunya adalah kerja jarak jauh meluas sehingga bisa bekerja tanpa pergi ke kantor. Banyak keluarga yang ingin membesarkan anak di lingkungan alami dengan sewa murah. Namun saat benar-benar pindah, ada masalah tak terduga. Misalnya tanpa mobil tak bisa belanja atau ke rumah sakit, hubungan tetangga lebih erat dari dugaan sehingga bingung. Di daerah, ikut kegiatan setempat kadang dianggap lumrah. Karena itu dikatakan penting mengunjungi kota beberapa kali dan merasakan hidup nyata sebelum memutuskan pindah. Ada pemerintah daerah yang menyediakan sistem "coba pindah" jangka pendek.',
    [Q('地方へ移り住む人が増えている理由として、正しいものはどれか。',['リモートワークで会社に通わなくても働けるようになったから','都会の家賃が安くなったから','地方に会社が増えたから','電車が便利になったから'],0,'Kerja jarak jauh.','リモートワークが広まり、会社に通わなくても働けるようになった'),
     Q('地方で暮らして、戸惑うことの例として挙げられているものはどれか。',['近所づきあいが思っていたより密なこと','家賃が高いこと','自然が少ないこと','店が多すぎること'],0,'Hubungan tetangga erat.','近所づきあいが思っていたより密で戸惑う',W,P2),
     Q('移住を決める前に、何が大切だと言っているか。',['何度か訪れて、実際の暮らしを体験しておくこと','すぐに家を買うこと','都会に戻らないと決めること','自治体に何も聞かないこと'],0,'Mencoba hidup nyata dulu.','何度かその町を訪れ、実際の暮らしを体験しておくことが大切',W,P1)]),
 Cc('「食品ロス」とは、まだ食べられるのに捨てられてしまう食べ物のことだ。日本では、一年間に約五百万トン以上の食品ロスが出ているといわれ、その半分近くは家庭から出ている。\n家庭での食品ロスの主な原因は、買いすぎて使い切れないこと、食べ残し、そして賞味期限が切れて捨てることなどである。特に、「賞味期限」を「食べられなくなる日」だと誤解している人が多いことが問題とされている。賞味期限は、「おいしく食べられる期限」であり、少し過ぎてもすぐに食べられなくなるわけではない。\nそこで、スーパーでは、期限が近づいた商品を安く売ったり、必要な分だけ買うことをすすめたりする取り組みが広がっている。私たち一人一人が、買い物の仕方を見直すことが大切だ。',
    '"Food loss" adalah makanan yang masih bisa dimakan tapi dibuang. Di Jepang katanya setahun keluar sekitar lima juta ton lebih, dan hampir separuhnya dari rumah tangga. Penyebab utama di rumah: membeli berlebih dan tak habis, sisa makanan, dan membuang karena tanggal kedaluwarsa lewat. Terutama masalah banyak yang salah paham bahwa "shoumi kigen" adalah hari makanan tak bisa dimakan. Sebenarnya itu "batas waktu rasa enak", dan bila lewat sedikit tak langsung tak bisa dimakan. Karena itu di supermarket berkembang upaya menjual murah barang mendekati batas dan menganjurkan membeli seperlunya. Penting bagi tiap orang meninjau cara belanja.',
    [Q('食品ロスの約半分は、どこから出ているか。',['家庭','スーパー','工場','農家'],0,'Rumah tangga.','その半分近くは家庭から出ている'),
     Q('「賞味期限」について、正しいものはどれか。',['おいしく食べられる期限で、少し過ぎてもすぐに食べられなくなるわけではない','過ぎたら必ず食べられない','食べると病気になる日','買ってはいけない日'],0,'Batas rasa enak.','「おいしく食べられる期限」であり、少し過ぎてもすぐに食べられなくなるわけではない',W,P2),
     Q('筆者が最後に言いたいことは何か。',['一人一人が買い物の仕方を見直すことが大切だ','スーパーが悪い','家庭は何もしなくていい','賞味期限をなくすべきだ'],0,'Tinjau cara belanja.','私たち一人一人が、買い物の仕方を見直すことが大切だ',W,P1)]),
 Cc('私は大学生のとき、初めてアルバイトで居酒屋の店員になった。最初は注文を間違えたり、お皿を落としたりして、毎日のように店長に注意された。何度も辞めたいと思った。\nそんなある日、常連のお客さんが、私に「いつも元気な挨拶で気持ちがいいよ」と声をかけてくれた。失敗ばかりだと思っていた私には、とても意外なことばだった。その日から、「うまくできなくても、元気に挨拶することだけは続けよう」と決めた。\n半年後、店長にも「ずいぶん成長したね」とほめられた。あのとき辞めなくて本当によかったと思う。仕事は、完璧にできなくても、続ける中で学べることがたくさんあると今は思っている。',
    'Saat mahasiswa, saya pertama kali kerja paruh waktu sebagai pelayan izakaya. Awalnya sering salah pesanan atau menjatuhkan piring, hampir tiap hari ditegur manajer. Berkali-kali ingin berhenti. Suatu hari pelanggan tetap menyapa, "Salam semangatmu selalu menyenangkan." Bagi saya yang merasa hanya gagal, itu tak terduga. Sejak hari itu saya memutuskan, "Meski belum becus, setidaknya terus menyapa dengan semangat." Setengah tahun kemudian manajer memuji, "Kamu sudah banyak berkembang." Saya merasa beruntung tidak berhenti waktu itu. Kini saya yakin meski tak sempurna, banyak yang bisa dipelajari dalam pekerjaan selama terus dijalani.',
    [Q('「私」が何度も辞めたいと思ったのはなぜか。',['注文を間違えたりして、毎日のように店長に注意されたから','給料が安かったから','店が遠かったから','お客さんが怖かったから'],0,'Sering ditegur.','毎日のように店長に注意された'),
     Q('「私」が続けようと決めたきっかけは何か。',['常連のお客さんに挨拶をほめられたこと','店長にほめられたこと','友達にすすめられたこと','給料が上がったこと'],0,'Dipuji pelanggan.','いつも元気な挨拶で気持ちがいいよ',W,P2),
     Q('「私」は今、仕事についてどう考えているか。',['完璧でなくても、続ける中で学べることがたくさんある','失敗したらすぐ辞めるべきだ','完璧にできなければ意味がない','アルバイトは学ぶことがない'],0,'Banyak yang dipelajari.','続ける中で学べることがたくさんある',W,P1)]),
 Cc('日本には、四季の移り変わりを大切にする文化がある。春は桜、夏は花火、秋は紅葉、冬は雪景色と、季節ごとの楽しみ方がある。食べ物にも「旬」という考え方があり、その季節に一番おいしく栄養がある食材を食べることがよいとされている。\n近年は、ハウス栽培や輸入のおかげで、一年中いろいろな食材が手に入る。便利になった反面、季節を感じる機会が減ったと感じる人もいる。\nそこで、旬の食材を使った給食を出したり、季節の行事を体験する授業を行ったりする学校が増えている。子どもたちが、自然や季節を身近に感じられるようにするための取り組みだ。',
    'Jepang memiliki budaya menghargai pergantian empat musim. Musim semi sakura, musim panas kembang api, musim gugur daun merah, musim dingin pemandangan salju — tiap musim ada cara menikmatinya. Pada makanan pun ada konsep "shun", yakni memakan bahan yang paling enak dan bergizi pada musimnya. Belakangan, berkat rumah kaca dan impor, berbagai bahan bisa didapat sepanjang tahun. Praktis, tetapi ada yang merasa kesempatan merasakan musim berkurang. Karena itu makin banyak sekolah menyajikan makan siang berbahan musiman dan menggelar pelajaran mengalami acara musiman. Upaya agar anak merasa dekat dengan alam dan musim.',
    [Q('「旬」とは何か。',['その季節に一番おいしく栄養がある食材','一年中取れる食材','輸入された食材','高い食材'],0,'Bahan paling enak musimnya.','その季節に一番おいしく栄養がある食材'),
     Q('便利になった反面、どんなことが起きているか。',['季節を感じる機会が減ったと感じる人がいる','食べ物がなくなった','季節がなくなった','食材が高くなった'],0,'Kurang merasakan musim.','季節を感じる機会が減ったと感じる人もいる',W,P2),
     Q('学校の取り組みの目的は何か。',['子どもたちが自然や季節を身近に感じられるようにすること','給食を安くすること','授業を減らすこと','外国の食べ物を教えること'],0,'Mendekatkan anak dengan musim.','自然や季節を身近に感じられるようにするための取り組み',W,P1)]),
 Cc('スマートフォンの普及で、私たちはいつでもどこでも情報を調べられるようになった。分からない言葉は、すぐに画面で検索すれば答えが出る。確かに便利だが、その一方で、自分の頭で考える機会が減っているのではないかという指摘もある。\nある大学の調査では、スマートフォンですぐに答えを調べる習慣のある学生は、そうでない学生より、長い時間、一つの問題を考え続けるのが苦手だという結果が出た。「考える前に調べる」習慣が、粘り強く考える力を弱めている可能性があるという。\nもちろん、スマートフォンを使うこと自体が悪いわけではない。大切なのは、調べる前に、まず自分で少し考えてみることだ。そうすれば、情報も、より深く理解できるのではないだろうか。',
    'Dengan meluasnya ponsel pintar, kita bisa mencari informasi kapan pun di mana pun. Kata yang tak dipahami segera dicari lewat layar dan jawaban muncul. Memang praktis, tetapi ada pula kritik bahwa kesempatan berpikir dengan kepala sendiri berkurang. Survei sebuah universitas menunjukkan mahasiswa yang terbiasa langsung mencari jawaban di ponsel lebih lemah dalam terus memikirkan satu masalah dalam waktu lama dibanding yang tidak. Kebiasaan "mencari sebelum berpikir" mungkin melemahkan daya pikir yang gigih. Tentu bukan berarti memakai ponsel itu buruk. Yang penting, sebelum mencari, coba pikirkan sendiri sedikit. Dengan begitu informasi bisa dipahami lebih dalam.',
    [Q('大学の調査で、どんなことがわかったか。',['すぐ調べる習慣のある学生は、長く考え続けるのが苦手だった','スマホを使う学生の成績が高かった','学生は全員よく考えていた','調べる習慣のない学生が苦手だった'],0,'Yang langsung mencari lemah.','長い時間、一つの問題を考え続けるのが苦手だという結果'),
     Q('筆者は、スマートフォンについてどう考えているか。',['使うこと自体が悪いわけではない','使ってはいけない','持たないほうがよい','学校に持ち込むべきだ'],0,'Memakainya sendiri tak buruk.','スマートフォンを使うこと自体が悪いわけではない',W,P2),
     Q('筆者が大切だと言っていることは何か。',['調べる前に、まず自分で少し考えてみること','すぐに調べること','何も調べないこと','友達に聞くこと'],0,'Pikirkan dulu sendiri.','調べる前に、まず自分で少し考えてみること',W,P1)]),
 Cc('私の町には、毎年秋に「収穫祭」という祭りがある。町の農家が、その年にとれた米や野菜、果物を持ち寄り、広場に並べて、自由に食べたり買ったりできる。\n祭りの目玉は、大きな鍋で作る「芋煮」だ。直径三メートルほどの鍋で、数百人分の芋煮を一度に作る。町の人が順番に並び、無料でふるまわれる。私は毎年、家族と並んで、湯気の立つ芋煮を食べるのが楽しみだ。\n祭りのもう一つの目的は、都会から来た人に、町の農業を知ってもらうことだ。去年は初めて、農家の人が畑の見学ツアーを開いた。参加者は、土に触れ、野菜の収穫を体験して、とても喜んでいた。',
    'Di kota saya tiap musim gugur ada festival panen. Petani kota membawa beras, sayur, buah hasil panen tahun itu, dipajang di lapangan dan boleh dimakan atau dibeli bebas. Andalan festival adalah "imoni" dalam panci besar. Panci berdiameter sekitar tiga meter membuat imoni untuk ratusan orang sekaligus. Warga antre bergiliran dan dibagikan gratis. Saya tiap tahun antre bersama keluarga dan menanti makan imoni yang berasap. Tujuan lain festival adalah memperkenalkan pertanian kota pada orang kota. Tahun lalu untuk pertama kalinya petani mengadakan tur kunjungan ladang. Peserta menyentuh tanah dan mengalami memanen sayur dan sangat senang.',
    [Q('収穫祭の目玉は何か。',['大きな鍋で作る芋煮','花火大会','マラソン','音楽会'],0,'Imoni dalam panci besar.','祭りの目玉は、大きな鍋で作る「芋煮」だ'),
     Q('芋煮はどのようにふるまわれるか。',['町の人が順番に並び、無料でもらえる','一杯五百円で売られる','予約した人だけがもらえる','家に配られる'],0,'Gratis, antre bergiliran.','順番に並び、無料でふるまわれる',W,P2),
     Q('去年の祭りで、初めて行われたことは何か。',['農家の人が畑の見学ツアーを開いたこと','芋煮が無料になったこと','祭りが夜に行われたこと','都会で祭りをしたこと'],0,'Tur kunjungan ladang.','去年は初めて、農家の人が畑の見学ツアーを開いた',W,P2)]),
 Cc('日本の高齢化が進み、一人で暮らすお年寄りが増えている。体が弱くなっても、住み慣れた家で暮らし続けたいと望む人は多い。しかし、買い物や掃除、病院への通院などが難しくなり、困っているお年寄りも少なくない。\nそこで、地域の人たちが助け合う仕組みを作る町が増えている。例えば、元気なお年寄りが、少し困っている人の買い物を手伝う。若い人が、重い荷物を運んだり、病院に付き添ったりする。\n助けられる側だけでなく、助ける側にとっても、人の役に立つ喜びや、外に出るきっかけになる。誰もが助け合って暮らせる町づくりが、これからますます大切になるだろう。',
    'Dengan menuanya penduduk Jepang, lansia yang hidup sendiri bertambah. Banyak yang ingin terus tinggal di rumah yang akrab meski tubuh melemah. Namun belanja, bersih-bersih, dan ke rumah sakit menjadi sulit dan tak sedikit lansia kesusahan. Karena itu makin banyak kota membuat sistem warga saling membantu. Misalnya lansia yang sehat membantu belanja orang yang agak kesulitan. Anak muda membawa barang berat atau menemani ke rumah sakit. Bukan hanya yang dibantu, bagi yang membantu pun jadi kebahagiaan berguna dan alasan keluar rumah. Membangun kota yang saling membantu akan makin penting.',
    [Q('一人で暮らすお年寄りの多くが望んでいることは何か。',['住み慣れた家で暮らし続けること','施設に入ること','都会に引っ越すこと','一人で旅行すること'],0,'Tetap tinggal di rumah.','住み慣れた家で暮らし続けたいと望む人は多い'),
     Q('地域の助け合いの例として、書かれているものはどれか。',['元気なお年寄りが、困っている人の買い物を手伝う','お年寄りだけで旅行する','若い人が引っ越す','学校が休みになる'],0,'Lansia sehat bantu belanja.','元気なお年寄りが、少し困っている人の買い物を手伝う',W,P2),
     Q('助ける側にとっての良い点は何か。',['人の役に立つ喜びや、外に出るきっかけになること','お金がもらえること','仕事が減ること','家が広くなること'],0,'Rasa berguna dan alasan keluar.','人の役に立つ喜びや、外に出るきっかけになる',W,P2)]),
 Cc('私の学校では、毎年「職場体験」という授業がある。中学二年生が、三日間、地域の店や会社で実際に働く体験をするものだ。\n私は、近所のパン屋さんで働かせてもらった。朝四時に出勤し、パンの生地をこねたり、焼きあがったパンを並べたりした。想像していたより体力が必要で、一日が終わるとくたくただった。しかし、焼きたてのパンを「おいしい」と言って買ってくれるお客さんの顔を見て、疲れが吹き飛んだ。\nこの体験を通して、働くことは大変だけれど、人に喜んでもらえるのがやりがいだと知った。将来の仕事を考えるとき、この経験を思い出したいと思う。',
    'Di sekolah saya tiap tahun ada pelajaran "pengalaman kerja". Siswa kelas dua SMP tiga hari mengalami bekerja di toko/perusahaan lokal. Saya bekerja di toko roti dekat rumah. Berangkat jam 4 pagi, mengaduk adonan dan menata roti panggangan. Perlu tenaga lebih dari bayangan; selesai sehari saya lemas. Namun melihat wajah pelanggan yang berkata "enak" saat membeli roti hangat, lelah hilang. Lewat pengalaman ini saya tahu kerja itu berat, tapi membuat orang senang adalah makna kerja. Saat memikirkan pekerjaan masa depan, saya ingin mengingat pengalaman ini.',
    [Q('職場体験は、どのような授業か。',['中学二年生が三日間、地域の店や会社で働く','高校生が一年間働く','大人が学校で働く','先生が店で働く'],0,'3 hari kerja di tempat setempat.','中学二年生が、三日間、地域の店や会社で実際に働く体験'),
     Q('「私」が疲れが吹き飛んだのはどんなときか。',['お客さんが「おいしい」と言って買ってくれたとき','家に帰ったとき','給料をもらったとき','昼ご飯を食べたとき'],0,'Saat pelanggan bilang enak.','「おいしい」と言って買ってくれるお客さんの顔を見て、疲れが吹き飛んだ',W,P2),
     Q('「私」は、この体験から何を学んだか。',['働くことは大変だが、人に喜んでもらえるのがやりがいだ','パン屋は楽な仕事だ','働くのは一人でいい','仕事はお金だけが目的だ'],0,'Kepuasan membuat orang senang.','人に喜んでもらえるのがやりがいだと知った',W,P1)]),
 Cc('「ありがとう」という言葉は、人間関係を良くする力を持っている。心理学の研究では、「ありがとう」と言われた人は、自分が役に立ったと感じ、次も人を助けようとする気持ちが強くなるという。\nまた、「ありがとう」と言うほうも、相手のよいところに気づくことで、前向きな気持ちになれる。つまり、感謝のことばは、言う人と言われる人の両方を幸せにするのだ。\nところが、家族や親しい友達には、かえって「ありがとう」を言いにくいという人も多い。「言わなくても分かるだろう」と思ってしまうからだ。しかし、身近な人こそ、言葉にして伝えることが大切だ。今日から一日一回、意識して感謝を口にしてみてはどうだろうか。',
    'Kata "terima kasih" punya kekuatan memperbaiki hubungan antarmanusia. Penelitian psikologi menunjukkan orang yang diucapi terima kasih merasa berguna dan makin ingin menolong lagi. Orang yang mengucapkan pun, dengan menyadari kebaikan lawan bicara, jadi berpikiran positif. Jadi, ucapan syukur membahagiakan yang mengucapkan dan yang diucapi. Namun banyak orang justru sulit mengucap "terima kasih" pada keluarga atau sahabat karena berpikir "tak diucap pun pasti paham". Padahal justru orang dekat penting diungkapkan dengan kata. Bagaimana kalau mulai hari ini, satu kali sehari, dengan sadar mengucapkan terima kasih?',
    [Q('「ありがとう」と言われた人は、どう感じるか。',['自分が役に立ったと感じ、また人を助けようとする','恥ずかしくなる','おこりたくなる','何も感じない'],0,'Merasa berguna.','自分が役に立ったと感じ、次も人を助けようとする気持ちが強くなる'),
     Q('家族や親しい友達に「ありがとう」を言いにくいのはなぜか。',['「言わなくても分かるだろう」と思ってしまうから','相手が怒るから','言葉を知らないから','時間がないから'],0,'Merasa tak perlu diucap.','「言わなくても分かるだろう」と思ってしまうから',W,P2),
     Q('筆者は何をすすめているか。',['一日一回、意識して感謝を口にすること','毎日手紙を書くこと','家族と話さないこと','感謝されるのを待つこと'],0,'Ucap terima kasih sehari sekali.','今日から一日一回、意識して感謝を口にしてみてはどうだろうか',W,P1)]),
]
